--region handler
---按钮点击回调
function ActivityBossChallengeBossListCell:BtnOnClickHandler()
    local serverTime = GameUtils.GetServerTime()
    if self._cellData.endTime < serverTime then 
        GameUtils.Toast(localize("挑战完成"))
        return 
    end

    if self._cellData.startTime > serverTime then
        GameUtils.Toast(localize("挑战未开启"))
        return
    end
    
    if self._callback then
        self._callback()
    end
end
