--region public
---刷新cell
function ActivityBossChallengeBossListCell:RefreshCell(data)
    local serverTime = GameUtils.GetServerTime()
    self._cellData = data
    local roleImgPath = ActivityUtils.GetImageFullPath(data.drawingId)
    CfUtils.FillImage(self.ImgRole, roleImgPath)
    CfUtils.FillText(self.TxtName, data.name)

    self:PlayEnterAnimation()
    if data.endTime < serverTime then
        -- 关卡已关闭
        KTool.SetActive(self.OpenNode, false)
        KTool.SetActive(self.CloseNode, false)
        KTool.SetActive(self.CompleteNode, true)
        KTool.SetActive(self.ImgBgMask, true)
        KTool.SetActive(self.ImgRoleMask, true)
        KTool.SetActive(self.CloseTxtLeftTime, false)
        CfUtils.SetUISwitchImage(self.ImgBg, 2)
        return 
    end

    self:RefreshCountdown()
    if data.startTime > serverTime then
        -- 未开启
        KTool.SetActive(self.OpenNode, false)
        KTool.SetActive(self.CloseNode, true)
        KTool.SetActive(self.CompleteNode, false)
        KTool.SetActive(self.ImgBgMask, true)
        KTool.SetActive(self.ImgRoleMask, false)
        CfUtils.SetUISwitchImage(self.ImgBg, 2)
        return
    end
    
    KTool.SetActive(self.OpenNode, true)
    KTool.SetActive(self.CloseNode, false)
    KTool.SetActive(self.CompleteNode, false)
    KTool.SetActive(self.ImgBgMask, false)
    KTool.SetActive(self.ImgRoleMask, false)
    CfUtils.SetUISwitchImage(self.ImgBg, 1)
    CfUtils.FillText(self.TxtNumber, data.remainQuestNum)
    CfUtils.SetUISwitchImage(self.ImgTimeBg, checkInt(data.remainQuestNum) == 0 and 1 or 2)
    
end

---设置点击回调
function ActivityBossChallengeBossListCell:SetBtnCallBack(callback)
    self._callback = callback
end

---刷新倒计时
function ActivityBossChallengeBossListCell:RefreshCountdown()
    local serverTime = GameUtils.GetServerTime()
    if self._cellData.endTime < serverTime then
        local isActive =  KTool.IsActive(self.CloseTxtLeftTime.gameObject)
        if isActive then
            KTool.SetActive(self.CloseTxtLeftTime.gameObject,false)    
            self:RefreshCell(self._cellData)
        end
        return 
    end
    if self._cellData.startTime >= serverTime then
        CfUtils.FillText(self.OpenTxtLeftTime, ActivityUtils.ConventLeftTimeText(self._cellData.startTime))    
    else 
        local isActive = KTool.IsActive(self.CloseNode.gameObject)    
        if isActive then
            ---@type Engine.UI.UILuaDialog 
            local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.ActivityBossChallengeDialog)
            if isNotNull(dialog) then
                dialog.Env:InitData()
            end
        end 
    end
    CfUtils.FillText(self.CloseTxtLeftTime, localize('剩余关闭时间_num_', {_num_ = ActivityUtils.ConventLeftTimeText(self._cellData.endTime)}))
end

--播放入场动画
function ActivityBossChallengeBossListCell:PlayEnterAnimation()
    local serverTime = GameUtils.GetServerTime()
    local state = CellState.OPEN
    if self._cellData.endTime < serverTime then
        state = CellState.CLOSE
    elseif self._cellData.startTime > serverTime then
        state = CellState.LOCK
    else
        state = CellState.OPEN
    end

    self.AnimRoot:PlayQueued('UIBossFightDialogCellOpen' .. state)
    self.AnimRoot:PlayQueued('UIBossFightDialogCellIdle' .. state)
end
